import {LAYOUTS,findKey,FINGER_NAMES} from './data.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const start=[12,30,61],step=61,size=54;
const homeCols=[0,1,2,3,6,7,8,9];
const bases=[98,146,197,247,435,488,539,587];
export function keyboardMarkup(layout){let l=LAYOUTS[layout];let keys=l.rows.map((row,r)=>[...row].map((c,i)=>`<g class="key-cap" data-row="${r}" data-col="${i}" transform="translate(${start[r]+i*step} ${16+r*62})"><rect width="54" height="54" rx="7"/><text x="27" y="31">${esc(c.toUpperCase())}</text>${l.shift[r][i]&&l.shift[r][i]!==c.toUpperCase()?`<text class="key-alt" x="27" y="45">${esc(l.shift[r][i])}</text>`:''}${r===1&&(i===3||i===6)?'<path class="home-mark" d="M23 43h8"/>':''}</g>`).join('')).join('');
 const palms='<path class="palm" d="M68 386 83 300Q83 272 110 270L235 270Q265 270 278 297L318 356Q330 389 306 413L286 432H76Z"/><path class="palm" d="M616 386 601 300Q601 272 574 270L449 270Q419 270 406 297L366 356Q354 389 378 413L398 432H608Z"/>';
 let fingers=bases.map((b,i)=>{let cx=start[1]+homeCols[i]*step+27,cy=105;return`<path id="finger-${i}" class="finger" d="${fingerPath(b,cx,cy,i)}"/>`}).join('');
 let thumbs='<path id="finger-8" class="finger thumb" d="M267 354Q264 294 288 277Q309 266 326 291L344 325Q353 342 340 354Q315 376 299 373Z"/><path class="finger thumb" d="M417 354Q420 294 396 277Q375 266 358 291L340 325Q331 342 344 354Q369 376 385 373Z"/>';
 return `<div class="keyboard-wrap"><svg viewBox="${layout==='йцукен'?'0 -48 760 473':'0 0 760 425'}" class="keyboard-svg" role="img" aria-label="Экранная клавиатура ${esc(l.name)} и подсказки пальцев"><defs><linearGradient id="handFade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--hand-fill)" stop-opacity=".68"/><stop offset="1" stop-color="var(--hand-fill)" stop-opacity="0"/></linearGradient></defs><g class="key-layer">${layout==='йцукен'?'<g class="key-cap" data-row="-1" data-col="0" transform="translate(12 -42)"><rect width="54" height="44" rx="7"/><text x="27" y="25">Ё</text></g>':''}${keys}<g class="key-cap" data-row="3" data-col="0" transform="translate(197 202)"><rect width="367" height="48" rx="7"/><text class="space-label" x="183.5" y="29">пробел</text></g></g><g class="hands-layer">${palms}${fingers}${thumbs}</g></svg><p class="finger-hint" id="fingerHint"></p></div>`;
}
function fingerPath(base,x,y,i){let w=i===0||i===7?18:21,bottom=301;return`M${base-w} ${bottom} Q${base-w-5} 235 ${x-w} ${y+25} Q${x-w-3} ${y-22} ${x} ${y-24} Q${x+w+3} ${y-22} ${x+w} ${y+25} Q${base+w+6} 235 ${base+w} ${bottom} Z`}
export function updateKeyboard(root,layout,char,{keyboard=true,hands=true}={}){let wrap=root.querySelector('.keyboard-wrap');if(!wrap)return;wrap.hidden=!keyboard;wrap.classList.toggle('no-hands',!hands);root.querySelectorAll('.key-cap').forEach(k=>k.classList.remove('target'));root.querySelectorAll('.finger').forEach(f=>f.classList.remove('active-finger'));root.querySelector('#finger-8')?.setAttribute('d','M267 354Q264 294 288 277Q309 266 326 291L344 325Q353 342 340 354Q315 376 299 373Z');let key=findKey(char||'',layout);for(let i=0;i<8;i++){let p=root.querySelector('#finger-'+i),x=start[1]+homeCols[i]*step+27,y=105;if(key&&key.finger===i){x=key.row===-1?39:start[key.row]+key.col*step+27;y=key.row===-1?-18:43+key.row*62;p.classList.add('active-finger')}p.setAttribute('d',fingerPath(bases[i],x,y,i))}
 if(key){root.querySelector(`.key-cap[data-row="${key.row}"][data-col="${key.col}"]`)?.classList.add('target');if(key.finger===8){let thumb=root.querySelector('#finger-8');thumb?.classList.add('active-finger');thumb?.setAttribute('d','M267 354Q264 281 296 231Q313 211 332 233L354 267Q366 283 350 296Q325 315 301 348Z')}}
 let hint=root.querySelector('#fingerHint');hint.textContent=key?`${FINGER_NAMES[key.finger]} · ${char===' '?'пробел':char}${key.shift?' · удерживай Shift другой рукой':''}`:char?`Набери «${char}»`:'Возвращай пальцы на домашний ряд';
}
